def _help_guide2(doc, lang):
    if '<section id="guide2"' in doc:
        return doc
    i = doc.find('<section id="tips"')
    if i < 0:
        i = doc.find('<section id="privacy"')
    return doc[:i] + _HELP_GUIDE2[lang] + doc[i:] if i >= 0 else doc


_hp_en2 = HELP_PAGE.find('<div lang="en">')
